'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\r\n\r\n', [[''], ['']]],
  ['a\rb\r\nc\n', [['a'], ['b'], ['c']]],
  [',,', [['', '', '']]],
  ['""', [['']]],
  ['a"b,"c,d",', [['a"b', 'c,d', '']]],
  ['"say ""hi""",tail\r\n', [['say "hi"', 'tail']]],
  ['"\r\n\r\n\n\r",x\r\n', [['\r\n\r\n\n\r', 'x']]],
  ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['a😀,"😀"', [['a😀', '😀']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\n', [['a', 'b']], { delimiter: '\t' }],
  ['a b', [['a', 'b']], { delimiter: ' ' }],
  ['a\uD83Db', [['a', 'b']], { delimiter: '\uD83D' }],
  ['a\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
];

test('grammar is invariant under all two-boundary chunk splits', () => {
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    for (let i = 0; i <= text.length; i++) {
      for (let j = i; j <= text.length; j++) {
        const parser = createParser(options);
        const rows = [];
        for (const chunk of ['', text.slice(0, i), '', text.slice(i, j), '', text.slice(j), '']) {
          rows.push(...parser.push(chunk));
        }
        rows.push(...parser.end());
        assert.deepEqual(rows, expected, JSON.stringify({ text, i, j }));
        assert.deepEqual(parser.end(), []);
        assert.throws(() => parser.push(''), Error);
      }
    }
  }
});

test('push emits immediately at CR and never repeats rows', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('a,b\r'), [['a', 'b']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\n"c'), []);
  assert.deepEqual(parser.push('\r'), []);
  assert.deepEqual(parser.push('\nd"'), []);
  assert.deepEqual(parser.push('"e",f\n\nlast,'), [['c\r\nd"e', 'f'], ['']]);
  assert.deepEqual(parser.end(), [['last', '']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
});

test('delimiter and chunk validation, empty chunks, and parser independence', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, true, {}, []]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
    assert.throws(() => parse('', { delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const a = createParser();
  const b = createParser({ delimiter: ';' });
  for (const chunk of [undefined, null, 2, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => a.push(chunk), TypeError);
  }
  assert.deepEqual(a.push(''), []);
  assert.deepEqual(a.push('\uFEFF"a'), []);
  assert.deepEqual(b.push('x;y\r'), [['x', 'y']]);
  assert.deepEqual(a.push(',b"\n'), [['a,b']]);
  assert.deepEqual(b.push('\nz'), []);
  assert.deepEqual(a.end(), []);
  assert.deepEqual(b.end(), [['z']]);
  assert.throws(() => parse(42), TypeError);
  const empty = createParser();
  assert.deepEqual(empty.end(), []);
  assert.deepEqual(empty.end(), []);
  assert.throws(() => empty.push(''), Error);
});

test('syntax errors report physical lines across every split', () => {
  const errors = [
    ['"a"x', 1, false],
    ['"a" ', 1, false],
    ['"a"\t', 1, false],
    ['ok\r\n"a"x', 2, false],
    ['"a\r\nb\rc\nd"x', 4, false],
    ['"', 1, true],
    ['"a""', 1, true],
    ['"a\r\n', 2, true],
    ['ok\r\n"a\r\nb\rc\n', 5, true],
  ];
  for (const [text, line, atEnd] of errors) {
    const matches = error => error instanceof SyntaxError &&
      new RegExp(`\\bline ${line}\\b`).test(error.message);
    assert.throws(() => parse(text), matches);
    for (let i = 0; i <= text.length; i++) {
      for (let j = i; j <= text.length; j++) {
        const parser = createParser();
        const push = () => {
          parser.push(text.slice(0, i));
          parser.push('');
          parser.push(text.slice(i, j));
          parser.push(text.slice(j));
        };
        if (atEnd) {
          push();
          assert.throws(() => parser.end(), matches);
        } else {
          assert.throws(push, matches);
        }
      }
    }
  }
});

test('header conversion retains duplicate, special-key, padding and mutation contracts', () => {
  const names = Object.freeze(['x', 'x', 'x_2', 'x', '__proto__', 'constructor', 'toString', '']);
  const first = Object.freeze(['a', 'b', 'c', 'd', 'proto', 'ctor', 'str', 'empty', 'ignored']);
  const short = Object.freeze(['z']);
  const records = Object.freeze([names, first, short]);
  const options = Object.freeze({ header: true });
  const expected = toObjects(records, options);
  const text = names.join(',') + '\n' + first.join(',') + '\n' + short.join(',');
  const actual = parse(text, options);
  assert.deepEqual(actual, expected);
  assert.deepEqual(Object.keys(actual[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '']);
  assert.equal(actual[0].__proto__, 'proto');
  assert.equal(actual[0].constructor, 'ctor');
  assert.equal(actual[0].toString, 'str');
  assert.equal(actual[0][''], 'empty');
  assert.equal(actual[1].x, 'z');
  for (const key of Object.keys(actual[1]).slice(1)) assert.equal(actual[1][key], '');
  for (const object of actual) {
    assert.equal(Object.getPrototypeOf(object), Object.prototype);
    for (const key of Object.keys(object)) {
      const descriptor = Object.getOwnPropertyDescriptor(object, key);
      assert.equal(descriptor.enumerable, true);
      assert.equal(descriptor.writable, true);
      assert.equal(descriptor.configurable, true);
    }
  }
  assert.deepEqual(toObjects(Object.freeze([short]), Object.freeze({ header: names })), [expected[1]]);
  assert.deepEqual(toObjects(Object.freeze([short]), Object.freeze({ header: Object.freeze([]) })), [{}]);
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('x,x', options), []);
  assert.deepEqual(parse('x\ny', { header: false }), [['x'], ['y']]);
  for (const header of [false, null, 1, 'x']) {
    assert.throws(() => toObjects(records, { header }), TypeError);
  }
});

